// Fixed sample edition, 7 October 2026. Editorial images are remotely embedded with credits.
const newsSamples=[
{id:'india',category:'India · Politics',title:'Opposition lawmakers detained during election-chief protest',summary:'Police detained Rahul Gandhi and other opposition lawmakers at a protest over voter-list revisions. Opposition parties allege the changes favour the government; the election commission and government deny the accusations. The dispute raises questions about electoral accountability, protest rights and how competing claims are verified.',url:'https://apnews.com/article/45e94c3dc0c4570f1e6f59bc60a118cc',publisher:'Associated Press',image:'https://staticprintenglish.theprint.in/wp-content/uploads/2026/10/India_397-696x465.jpg',credit:'Adnan Abidi / Reuters',question:'Protest, policing, or accountability?',angle:'Notice which of those becomes the headline. Look for the allegations, the official response, and the evidence that would help resolve the dispute.',tag:'Accountability'},
{id:'chemistry',category:'World · Science',title:'Chemistry Nobel recognises work on molecular asymmetry',summary:'Henri Kagan and Kenso Soai were recognised for research into molecular handedness. The work explores how chemistry can favour one mirror-image form of a molecule, with implications for pharmaceutical development. The scientists, the discovery and its practical applications offer different entry points into the story.',url:'https://www.deutschlandfunk.de/der-nobelpreis-fuer-chemie-geht-an-den-franzosen-henri-kagan-und-kenso-soai-aus-japan-100.html',publisher:'Deutschlandfunk',image:'https://bilder.deutschlandfunk.de/93/8c/04/bd/938c04bd-89c5-435a-85da-f029c80e9e7d/nobelpreis-chemie-2026-100-1920x1080.jpg',credit:'Steffen Trumpf / dpa',question:'The people, the discovery, or its impact?',angle:'Different headlines explain different parts of the breakthrough. Ask whether practical applications are established, expected, or still speculative.',tag:'People'},
{id:'forest',category:'World · Environment',title:'Environmental-crime operation results in 233 arrests',summary:'An international operation against illegal mining, logging and wildlife trafficking led to 233 arrests across Latin America and the Caribbean. Investigators also examined financial networks connected to environmental crime. Arrest totals capture the enforcement activity, but longer-term ecological outcomes and local impacts are different questions.',url:'https://www.aa.com.tr/en/world/interpol-operation-nets-233-arrests-in-multi-nation-latin-american-environmental-crackdown/4081356',publisher:'Anadolu Agency',image:'https://web-cdnprod.aa.com.tr/uploads/Contents/2026/10/07/thumbs_b_c_12c266d455df52125a32cddf7b4d53a5.jpg',credit:'Image via Anadolu Agency',question:'Arrest numbers—or the networks behind them?',angle:'What changes when reporting follows the money? Look for local communities, the scale of environmental harm and the distinction between an arrest and a conviction.',tag:'Coverage gaps'},
{id:'cyber',category:'World · Technology',title:'Japan transfers alleged Qilin hacker to Germany',summary:'An alleged member of the Qilin ransomware group was arrested in Tokyo and extradited to Germany, according to reporting on the investigation. The case connects cybercrime enforcement with international cooperation. Allegations about a suspect should remain distinct from findings established through the legal process.',url:'https://www.tagesschau.de/inland/gesellschaft/nordrhein-westfalen-russische-hackergruppe-festnahme-100.html',publisher:'Tagesschau',image:'https://images.tagesschau.de/image/edbde3ea-4e89-47a6-89d1-07e87ba510b6/AAABoRebz48/AAABnSSvdEs/16x7/wdr-symbolbild-cyberkriminalitaet-100.jpg?overlay=829a71d9-4698-403c-8865-2e31c92d86b5&overlayModificationDate=AAABlxDi-1w&width=1280',credit:'IMAGO / Silas Stein · illustrative photo',question:'A security story or a legal-process story?',angle:'Separate allegations from established findings. Check who makes each claim and whether the reporting links to court records or official statements.',tag:'Evidence'}
];
function newsDialog(id){const index=newsSamples.findIndex(n=>n.id===id),n=newsSamples[index];if(!n)return;openDialog('News brief',`<img class="dialog-photo" src="${n.image}" alt="${esc(n.title)}"><p class="image-credit">${n.credit}</p><div class="reader-meta"><span>${n.category}</span><span>Sample edition · 1 min read</span></div><h2 class="dialog-title">${n.title}</h2><p class="dialog-intro">${n.summary}</p><div class="reader-question"><h3>${n.question}</h3><p>${n.angle}</p></div><a class="primary" target="_blank" rel="noopener noreferrer" href="${n.url}">Read source · ${n.publisher}</a><div class="detail-block" style="margin-top:20px"><h4>Curious how the lenses work?</h4><p>Try the comparison with fictional stories and publishers.</p><button class="outline" id="explore-from-dialog" style="margin-top:12px">Open perspective lab</button></div><div class="reader-nav"><span>${index+1} of ${newsSamples.length} stories</span><button data-news="${newsSamples[(index+1)%newsSamples.length].id}">Next quick read</button></div>`);$('#detail-dialog').scrollTop=0;}
function hookDialog(){openDialog('Perspective check',`<h2 class="dialog-title">A new metro line is announced.<br>What do you read first?</h2><p class="dialog-intro">Choose a headline. Then explore the perspective it might leave outside the frame.</p><div class="hook-choices"><button data-choice="0"><span>01 · The promise</span><strong>“A faster commute for the city.”</strong></button><button data-choice="1"><span>02 · The people</span><strong>“Families on the route seek answers.”</strong></button><button data-choice="2"><span>03 · The evidence</span><strong>“What the project documents reveal.”</strong></button></div><div id="hook-answer" aria-live="polite"></div>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.news)newsDialog(b.dataset.news);if(b.id==='hook-button'||b.id==='perspective-button')hookDialog();if(b.dataset.choice!==undefined){const i=Number(b.dataset.choice);const answers=[['You saw the promise. Now meet the people.','Travel-time benefits are one part of the story. The People lens reveals whether affected residents get a voice.','people'],['You heard the people. Now inspect the evidence.','Personal accounts matter. The Evidence lens helps you see which reporting also links to documents and named sources.','evidence'],['You checked the evidence. Now look for the gaps.','Documents have boundaries too. The Coverage gaps lens shows which contexts appear across the sample.','gaps']];const a=answers[i];document.querySelectorAll('[data-choice]').forEach(x=>x.classList.toggle('chosen',x===b));$('#hook-answer').innerHTML=`<div class="hook-answer"><h3>${a[0]}</h3><p>${a[1]}</p><button class="primary" data-open-lens="${a[2]}">Reveal the wider view</button></div>`;}if(b.dataset.openLens){chooseStory('metro');chooseLens(b.dataset.openLens);$('#detail-dialog').close();$('#lens').scrollIntoView({behavior:'smooth'});}});
$('#news-grid').innerHTML=newsSamples.map(n=>`<article class="news-tile"><button class="news-photo" data-news="${n.id}" aria-label="Read ${esc(n.title)}"><img src="${n.image}" alt="${esc(n.title)}" loading="lazy"><span>${n.category}</span></button><div class="news-body"><button class="news-title" data-news="${n.id}">${n.title}</button><p>${n.question}</p><div class="news-bottom"><span>1 min read</span><button data-news="${n.id}">Open brief ⊕</button></div></div></article>`).join('');
